import { searchQueryString } from "./search-query";

export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string; view: "summary" | "history" }
  | { kind: "funder"; id: string; view: "summary" | "history" }
  | { kind: "invalid" };

export const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
export const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/search") return { kind: "search" };
  const member = /^\/members\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return {
      kind: "member",
      id: member[1],
      view: member[2] ? "history" : "summary",
    };
  const funder = /^\/funders\/([^/]+)(?:\/(history))?\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return {
      kind: "funder",
      id: funder[1],
      view: funder[2] ? "history" : "summary",
    };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  membershipFrom: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDeclaration {
  sourceId: number;
  categoryId: number;
  categoryName: string;
  registeredAt: string | null;
  entries: FundingEntry[];
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: MemberDeclaration[];
  summary: {
    currencies: (Total & {
      currency: string;
      categories: (Total & { categoryId: number; categoryName: string })[];
    })[];
    entryCount: number;
    unknownCurrencyCount: number;
    firstRegisteredAt: string | null;
    lastRegisteredAt: string | null;
    undatedDeclarationCount: number;
  };
}

export interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDeclaration {
  member: MemberProfile;
  declaration: MemberDeclaration;
}

export interface FunderDetails {
  declarations: FunderDeclaration[];
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
    aliases: string[];
  };
  currencies: {
    currency: string;
    amount: string | null;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
<script lang="ts">
  import { page } from "$app/state";
  import MemberDeclarations from "./MemberDeclarations.svelte";
  import RegistrationTimeline from "./RegistrationTimeline.svelte";
  import {
    categoryBars,
    memberHref,
    type MemberDetails,
  } from "./lib/entity-details";
  import { formatPounds, summarizeMember } from "./lib/member-summary";
  let {
    details,
    summary,
  }: { details: MemberDetails; summary: ReturnType<typeof summarizeMember> } =
    $props();
  const bars = $derived(categoryBars(summary.categories, "total"));
  const baseline = $derived(
    bars.reduce((total, bar) => total + (bar.negative ? bar.width : 0), 0),
  );
</script>

<div class="member-summary-top">
  <section class="member-breakdown" aria-labelledby="breakdown-heading">
    <h2 id="breakdown-heading">Declared value by category</h2>
    {#if summary.categories.length}
      <ul class="category-list" style:--baseline={`${baseline}%`}>
        {#each summary.categories as category, index}
          <li>
            <div class="category-label">
              <span>{category.categoryName}</span><span class="amount"
                >{formatPounds(category.amount)}</span
              >
            </div>
            <div class="signed-bar" aria-hidden="true">
              <span
                class:negative={bars[index].negative}
                style:width={`${bars[index].width}%`}
              ></span>
            </div>
            {#if category.unknownAmountCount}<p class="partial-note">
                Some amounts unavailable
              </p>{/if}
          </li>
        {/each}
      </ul>
    {:else}<p class="empty-details">No known declared values available.</p>{/if}
  </section>
  <RegistrationTimeline
    context="earnings"
    months={summary.earnings}
    undated={summary.undated}
  />
</div>
<section aria-labelledby="recent-declarations-heading">
  <div class="detail-section-heading">
    <h2 id="recent-declarations-heading">Recent declarations</h2>
  </div>
  {#if details.declarations.length}<MemberDeclarations
      declarations={details.declarations.slice(0, 5)}
    />{:else}<p class="empty-details">
      No declarations are stored for this MP.
    </p>{/if}
  <a
    class="text-button history-link"
    href={memberHref(details.member.id, "history", page.url.searchParams)}
    >View declaration history</a
  >
</section>

